// Element-only parser attachment lifetime (parser-display: the item_parsers
// control table), proven against the REAL store graph in-process: the
// scan-shaped PutItem upsert semantics plus the store attachment accessors.
// Two properties, straight from the spec scenarios:
//
//   - Re-scan survival: a re-scan upserts the item row by file_id PRESERVING
//     its id (B3), so an element-only attachment keyed to the id survives the
//     re-scan untouched.
//   - Re-identify cleanup: a root move re-identifies a file — the scanner
//     mints a NEW file_id and therefore a NEW item identity, which starts
//     with NO attachments (nothing propagates across identities, siblings
//     included); and when the old identity's rows are removed, its
//     attachments go with them (orphan-tolerant read).
package itest

import (
	"context"
	"fmt"
	"path/filepath"
	"testing"

	"github.com/mellifera/mellifera/internal/store"
)

// TestElement_Parsers_ReservationLifetime drives attach → re-scan →
// re-identify over the real store. It is the store-level joint behind boxes
// 3.3/4.1 (api surface + queue derivation both consume these accessors).
func TestElement_Parsers_AttachmentLifetime(t *testing.T) {
	ctx := context.Background()
	st, err := store.Open(ctx, filepath.Join(t.TempDir(), "element-parsers.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })

	libID, err := st.CreateLibrary(ctx, "serial", t.TempDir(), "anime")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}

	// scanPut mirrors the scan path: itemID is the deterministic composite of
	// (libraryID, file_id) — fmt.Sprintf("itm_%d_%s", libID, fileID), the
	// scan.itemID shape (that helper is unexported) — and PutItem upserts by
	// file_id preserving the id.
	scanPut := func(t *testing.T, fileID string) string {
		t.Helper()
		id := fmt.Sprintf("itm_%d_%s", libID, fileID)
		it := store.Item{
			ID: id, ModuleID: "serial", LibraryID: libID, FileID: fileID,
			RelativePath:  "show/" + fileID + ".mkv",
			MediaType:     "video",
			Document:      []byte(`{"parsed":{"series_relative_path":"show"}}`),
			SchemaVersion: 1,
		}
		if err := st.PutItem(ctx, it); err != nil {
			t.Fatalf("PutItem %s: %v", id, err)
		}
		return id
	}

	attached := scanPut(t, "file-1")
	sibling := scanPut(t, "file-2")

	if err := st.SetItemParsers(ctx, attached, []string{"anitomy"}); err != nil {
		t.Fatalf("SetItemParsers: %v", err)
	}

	// RE-SCAN (same root): the scanner re-observes the same file_id, so the
	// upsert lands on the same item id — the attachment must survive.
	attached = scanPut(t, "file-1")
	got, err := st.ListItemParsers(ctx, attached)
	if err != nil {
		t.Fatalf("ListItemParsers after rescan: %v", err)
	}
	if len(got) != 1 || got[0] != "anitomy" {
		t.Fatalf("after rescan: attachments = %v, want [anitomy] (re-scan survival)", got)
	}
	// Sibling isolation: the re-scan of the sibling (no attachment of its
	// own) surfaces nothing.
	if got, err := st.ListItemParsers(ctx, sibling); err != nil || len(got) != 0 {
		t.Fatalf("sibling attachments = %v, err = %v, want empty", got, err)
	}

	// RE-IDENTIFY (root move): the moved file carries a NEW file_id, so the
	// scan mints a NEW item identity. The new identity starts with NO
	// attachments — nothing copies across identities.
	reidentified := scanPut(t, "file-1-moved")
	if got, err := st.ListItemParsers(ctx, reidentified); err != nil || len(got) != 0 {
		t.Fatalf("re-identified attachments = %v, err = %v, want empty (die with identity)", got, err)
	}
	// The re-identify cleanup removes the old item rows; the old attachments
	// are removed together with them — the read is orphan-tolerant, never
	// surfacing rows whose item is gone.
	if _, err := st.DB().ExecContext(ctx, "DELETE FROM items WHERE id = ?", fmt.Sprintf("itm_%d_file-1", libID)); err != nil {
		t.Fatalf("remove re-identified-away item rows: %v", err)
	}
	if got, err := st.ListItemParsers(ctx, fmt.Sprintf("itm_%d_file-1", libID)); err != nil || len(got) != 0 {
		t.Fatalf("removed identity's attachments = %v, err = %v, want empty", got, err)
	}
}
